import test from "node:test";
import assert from "node:assert/strict";
import {
  log,
  debug,
  info,
  warn,
  error,
  setLevel,
  getLevel,
} from "../lib/logger.mjs";

function capture(fn) {
  const original = console.error;
  const lines = [];
  console.error = (msg) => lines.push(msg);
  try {
    fn();
  } finally {
    console.error = original;
  }
  return lines;
}

test("default level is info", () => {
  setLevel("info");
  assert.equal(getLevel(), "info");
});

test("messages at or above the active level are emitted", () => {
  setLevel("info");
  const lines = capture(() => {
    info("info-msg");
    warn("warn-msg");
    error("error-msg");
  });
  assert.deepEqual(lines, ["info-msg", "warn-msg", "error-msg"]);
});

test("messages below the active level are suppressed", () => {
  setLevel("info");
  const lines = capture(() => debug("debug-msg"));
  assert.deepEqual(lines, []);
});

test("setLevel('debug') re-enables debug output", () => {
  setLevel("debug");
  const lines = capture(() => debug("debug-msg"));
  assert.deepEqual(lines, ["debug-msg"]);
  setLevel("info");
});

test("log() still emits at the default level", () => {
  setLevel("info");
  const lines = capture(() => log("plain-msg"));
  assert.deepEqual(lines, ["plain-msg"]);
});

test("setLevel rejects unknown levels", () => {
  assert.throws(() => setLevel("verbose"));
});
